let calls = 0;
function slowSquare(n) { calls++; return n * n; }
function memo(fn) {
  const cache = new Map();
  return (n) => {
    if (!cache.has(n)) cache.set(n, fn(n));
    return cache.get(n);
  };
}
const sq = memo(slowSquare);
console.log(sq(4), sq(4), sq(5), sq(4));
console.log(calls);

